package com.hotel.pms.api.controller;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.hotel.pms.common.annotation.OperationLog;import com.hotel.pms.common.dto.*;import com.hotel.pms.common.result.Result;import com.hotel.pms.service.payment.DepositService;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.Parameter;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.web.bind.annotation.*;import java.util.List;/** * 押金管理控制器 * <p> * 处理押金收取、退还、查询等操作 * </p> *  * @author PMS开发团队 * @since 1.0.0 */@Slf4j@RestController@RequestMapping("/api/v1/deposits")@RequiredArgsConstructor@Tag(name = "押金管理", description = "押金收取、退还、查询等操作")public class DepositController {        private final DepositService depositService;        /**     * 收取押金     * <p>     * 为客人收取入住押金     * </p>     *      * @param dto 押金收取请求     * @return 押金信息     */    @OperationLog(module = "押金管理", action = "收取押金", targetType = "押金")    @PostMapping("/collect")    @Operation(summary = "收取押金", description = "为客人收取入住押金")    public Result<DepositVO> collectDeposit(@Valid @RequestBody DepositCollectDTO dto) {        DepositVO result = depositService.collectDeposit(dto);        return Result.success(result);    }        /**     * 退还押金     * <p>     * 对已收取的押金进行退还操作，支持部分退还     * </p>     *      * @param id 押金ID     * @param dto 退还请求     * @return 更新后的押金信息     */    @OperationLog(module = "押金管理", action = "退还押金", targetType = "押金", targetIdParam = "id")    @PostMapping("/{id}/refund")    @Operation(summary = "退还押金", description = "对已收取的押金进行退还操作")    public Result<DepositVO> refundDeposit(            @Parameter(description = "押金ID") @PathVariable Long id,            @Valid @RequestBody DepositRefundDTO dto) {        DepositVO result = depositService.refundDeposit(id, dto);        return Result.success(result);    }        /**     * 查询押金列表     * <p>     * 根据条件分页查询押金记录     * </p>     *      * @param queryDTO 查询条件     * @return 押金列表     */    @GetMapping    @Operation(summary = "查询押金列表", description = "根据条件分页查询押金记录")    public Result<Page<DepositVO>> list(DepositQueryDTO queryDTO) {        Page<DepositVO> result = depositService.list(queryDTO);        return Result.success(result);    }        /**     * 查询押金详情     * <p>     * 根据押金ID查询详细信息     * </p>     *      * @param id 押金ID     * @return 押金信息     */    @GetMapping("/{id}")    @Operation(summary = "查询押金详情", description = "根据押金ID查询详细信息")    public Result<DepositVO> getById(@Parameter(description = "押金ID") @PathVariable Long id) {        DepositVO result = depositService.getById(id);        return Result.success(result);    }        /**     * 根据入住单ID查询押金     * <p>     * 查询指定入住单关联的所有押金记录     * </p>     *      * @param stayId 入住单ID     * @return 押金列表     */    @GetMapping("/stay/{stayId}")    @Operation(summary = "查询入住单押金", description = "根据入住单ID查询关联的押金记录")    public Result<List<DepositVO>> getByStayId(            @Parameter(description = "入住单ID") @PathVariable Long stayId) {        List<DepositVO> result = depositService.getByStayId(stayId);        return Result.success(result);    }    /**     * 押金抵扣房费     * <p>     * 将押金转为房费支付，减少押金余额并记录房费支付交易流水     * </p>     *     * @param id 押金ID     * @param dto 抵扣请求     * @return 更新后的押金信息     */    @OperationLog(module = "押金管理", action = "押金抵扣房费", targetType = "押金", targetIdParam = "id")    @PostMapping("/{id}/deduct")    @Operation(summary = "押金抵扣房费", description = "将押金转为房费支付")    public Result<DepositVO> deductDepositForRoomFee(            @Parameter(description = "押金ID") @PathVariable Long id,            @Valid @RequestBody DepositDeductDTO dto) {        DepositVO result = depositService.deductDepositForRoomFee(id, dto);        return Result.success(result);    }}